func _finish25i_gate_texture_matches(entry: Dictionary, texture: Texture2D) -> bool:
	# Only the existing Field Gate module may own its source-checked ImageTexture.
	# This is NOT the former DT "unknown path succeeds" rule.
	if _finish25i==null or _current_scene==null or _current_scene.scene_id!=&"ch4_s0_luoyang_gate" or entry.get("gate_module_object")!=true or texture==null or not _finish25i._owned(true,true): return false
