	if state.is_empty() or state.get("released",true) or not state.get("field") is WeakRef or state.field.get_ref()!=self or not state.get("scene") is WeakRef or state.scene.get_ref()!=_current_scene or not state.get("layout") is WeakRef or state.layout.get_ref()!=_current_scene.map_layout: return false
	var gate: RefCounted=_gate_moat_runtime
	if gate==null or gate.get_script()!=GATE_MOAT_RUNTIME or not gate.get("_error") is String or gate.get("_error")!="" or not gate.get("_config") is Dictionary or gate.get("_config").is_empty(): return false
	var first: Variant=state.get("first")
	var manifest: Variant=gate.get("_manifest")
	var cache: Variant=gate.get("_textures")
	var path: String=String(entry.get("texture",""))
	if not first is Dictionary or not manifest is Dictionary or not manifest.get("asset_sha256") is Dictionary or not cache is Dictionary or path=="" or not cache.has(path): return false
	if first.get(GATE_FORTIFICATION.MANIFEST_PATH)!=GATE_FORTIFICATION.MANIFEST_SHA or first.get(GATE_FORTIFICATION.AUTHOR_PATH)!=GATE_FORTIFICATION.AUTHOR_SHA or not first.has("res://scripts/city/luoyang_gate_moat_runtime_20261013.gd") or not first.has("res://scripts/city/luoyang_gate_fortification_contract_20261013.gd"): return false
	var expected_sha: Variant=manifest.asset_sha256.get(path)
	if not expected_sha is String or expected_sha.length()!=64 or first.get(path)!=expected_sha: return false
	# Full published row, including all atlas/transform/source flags, must match.
	var payload: Variant=state.get("payload")
	if not payload is Dictionary or not payload.get("effective_navigation") is Array: return false
	var matched: int=0
	for row: Dictionary in payload.effective_navigation:
		if String(row.get("id",""))!=String(entry.get("id","")): continue
		if var_to_bytes(row)!=var_to_bytes(entry): return false
		matched+=1
	if matched!=1: return false
	var base: Variant=cache[path]
	if not base is ImageTexture: return false
	if entry.has("gate_atlas_region"):
		var region: Variant=entry.gate_atlas_region
		if not region is Rect2i or region.position.x<0 or region.position.y<0 or region.size.x<=0 or region.size.y<=0 or region.end.x>base.get_width() or region.end.y>base.get_height(): return false
		var atlas: AtlasTexture=texture as AtlasTexture
		return atlas!=null and atlas.atlas==base and atlas.region==Rect2(region) and atlas.margin==Rect2() and not atlas.filter_clip
	return texture==base

